extends Node
var p
func _ready() -> void:
	p = get_meta("viento_project")
	call_deferred("_run")
func _probe(label: String) -> void:
	print("VIENTO_CLOCK_PROBE:" + JSON.stringify({"label": label, "clock": {"idleFrame": Engine.get_process_frames(), "physicsFrame": Engine.get_physics_frames()}, "used": p.host.get_ref().execution_budget.snapshot()}))
func _finish() -> void:
	p.host.get_ref().finish_project()
func _run() -> void:
	var host = p.host.get_ref()
	for index in range(64):
		p.publish_event("tick", true)
		host.flush_requests()
	p.write_state("switched", true)
	_probe("before-switch")
	p.request_scene("12345678-1234-4234-8234-123456789abd")

